// @ts-nocheck
import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Avatar from 'flarum/common/components/Avatar';
export default class PostTipListModal extends Modal {
  className() {
    return 'PostTipListModal Modal--small';
  }
  title() {
    return app.translator.trans('ygpynet-point-system.forum.tip_list.title');
  }
  content() {
    const icon = app.forum.attribute('pointSystem.currency_icon') || 'fas fa-coins';
    const tips = this.attrs.post.attribute('pointSystemTips') || [];
    if (tips.length === 0) {
      return m("div", {
        className: "Modal-body"
      }, m("p", {
        className: "PostTipListModal-empty"
      }, app.translator.trans('ygpynet-point-system.forum.tip_list.empty')));
    }
    const total = tips.reduce((sum, t) => sum + (Number(t.amount) || 0), 0);
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "PostTipListModal-summary"
    }, m("i", {
      className: icon,
      "aria-hidden": "true"
    }), m("span", null, app.translator.trans('ygpynet-point-system.forum.tip_list.total', {
      total: total.toLocaleString(),
      count: tips.length
    }))), m("ul", {
      className: "PostTipListModal-list"
    }, tips.map(t => {
      // Prefer a fully-loaded user from the store (already on this page).
      // Otherwise synthesize one from the serialized sender data so the
      // avatar + profile link render even for tippers not present here.
      const existing = app.store.getById('users', String(t.senderId));
      const user = existing || app.store.pushPayload({
        data: {
          type: 'users',
          id: String(t.senderId),
          attributes: {
            username: t.senderUsername,
            displayName: t.senderName,
            avatarUrl: t.senderAvatarUrl
          }
        }
      });
      const username = t.senderUsername || (existing && typeof existing.username === 'function' ? existing.username() : null);
      const name = m("span", {
        className: "PostTipListModal-name"
      }, t.senderName);
      return m("li", {
        className: "PostTipListModal-item",
        key: t.senderId
      }, m(Avatar, {
        user: user
      }), username ? m("a", {
        href: app.route('user', {
          username
        }),
        className: "PostTipListModal-nameLink"
      }, name) : name, m("span", {
        className: "PostTipListModal-amount"
      }, m("i", {
        className: icon,
        "aria-hidden": "true"
      }), Number(t.amount).toLocaleString()));
    })));
  }
}
flarum.reg.add('ygpynet-point-system', 'forum/components/PostTipListModal', PostTipListModal);